const trk = $('Read Deal Tracker').all().map(function (i) { return i.json; });
const invRaw = $('Read INVESTORS').all().map(function (i) { return i.json; });
const stRaw = $('Read STARTUPS').all().map(function (i) { return i.json; });
const pipe = $input.all().map(function (i) { return i.json; });
if (pipe.length < 500) { throw new Error('ABORT: PIPELINE only ' + pipe.length); }
if (trk.length < 200) { throw new Error('ABORT: tracker only ' + trk.length + ' rows - truncated'); }

const TAGS = [
  ['health', /health|medtech|bio|clinic|pharma|life science|wellness|fitness|diagnost|hospital|patient|doctor/],
  ['fintech', /fintech|lending|insur|payment|banking|wealth|credit|financial|neobank/],
  ['saas', /saas|b2b|enterprise|software|platform|api|devtool|cloud|workflow|automation/],
  ['consumer', /consumer|d2c|b2c|retail|fmcg|food|beverage|fashion|beauty|apparel|coffee|restaurant|cafe|grocer|kitchen|snack|personal care/],
  ['deeptech', /deeptech|deep tech|\bai\b|artificial intelligence|\bml\b|robot|iot|semiconductor|space|drone|quantum|computer vision|hardware/],
  ['climate', /climate|clean|energy|solar|ev\b|electric vehicle|sustain|green|water|waste|carbon|recycl/],
  ['edtech', /edtech|education|learning|skill|training|exam|student|course/],
  ['logistics', /logistic|supply chain|mobility|delivery|freight|shipping|transport|warehous/],
  ['agritech', /agri|farm|agtech|crop/],
  ['hrtech', /hrtech|\bhr\b|recruit|talent|hiring|staffing|workforce/],
  ['proptech', /proptech|real estate|construction|coworking|interior|windoor|building/],
  ['media', /media|gaming|content|entertainment|creator|social|dating|travel|music|video/]
];
function tagsOf(txt) { const t = s(txt).toLowerCase(); const o = {}; for (const p of TAGS) { if (p[1].test(t)) { o[p[0]] = 1; } } return Object.keys(o); }
function startupStage(txt) {
  const t = s(txt).toLowerCase();
  if (/series b|growth|series c/.test(t)) { return 4; }
  if (/series a/.test(t)) { return 3; }
  if (/pilot|traction|early revenue|revenue|mvp|launched/.test(t)) { return 2; }
  if (/\bseed\b/.test(t) && !/pre-?seed/.test(t)) { return 1; }
  if (/pre-?seed|ideation|concept|idea|prototype/.test(t)) { return 0; }
  return 1;
}
function investorBand(txt) {
  const t = s(txt).toLowerCase(); const h = [];
  if (/pre-?seed|preseed/.test(t)) { h.push(0); }
  if (/\bseed\b/.test(t)) { h.push(1); }
  if (/pilot|traction|early|pre-?series a|pre series a/.test(t)) { h.push(2); }
  if (/series a/.test(t)) { h.push(3); }
  if (/series b|series c|growth|late|pre-?ipo/.test(t)) { h.push(4); }
  if (!h.length) { return null; }
  return [Math.min.apply(null, h), Math.max.apply(null, h)];
}
function toCr(txt) {
  const t = s(txt).replace(/,/g, ''); if (!t) { return null; }
  let m = t.match(/(?:US\$|\$)\s*([\d.]+)\s*M/i); if (m) { return parseFloat(m[1]) * 8.5; }
  m = t.match(/(?:US\$|\$)\s*([\d.]+)\s*K/i); if (m) { return parseFloat(m[1]) * 0.0085; }
  m = t.match(/([\d.]+)\s*(?:-|to|–)\s*[\d.]+\s*Cr/i); if (m) { return parseFloat(m[1]); }
  m = t.match(/([\d.]+)\s*Cr/i); if (m) { return parseFloat(m[1]); }
  m = t.match(/([\d.]+)\s*Lakh/i); if (m) { return parseFloat(m[1]) / 100; }
  return null;
}
const FLOOR_FIX = { a2dventures: 0.85, mintvc: 0.5, pipersireca: 1.0 };
const book = []; const seenInv = {};
for (const r of invRaw) {
  const n = s(r.investor); if (!n) { continue; }
  if (s(r.do_not_contact).toLowerCase() === 'yes') { continue; }
  const k = nz(n); if (seenInv[k]) { continue; } seenInv[k] = 1;
  let floor = toCr(r.cheque_inr_cr); if (FLOOR_FIX[k] !== undefined) { floor = FLOOR_FIX[k]; }
  book.push({ key: k, agnostic: /agno/i.test(s(r.sector)), tags: tagsOf(r.sector), band: investorBand(r.stage), floor: floor });
}
const cols = Object.keys(trk[0] || {}); let cInv = null; const cDeals = [];
for (const c of cols) { const l = c.toLowerCase();
  if (!cInv && (l.indexOf('investor') >= 0 || l.indexOf('vc name') >= 0)) { cInv = c; }
  if (l.indexOf('deals shared') >= 0 || l.indexOf('latest deal') >= 0 || l.indexOf('picked') >= 0) { cDeals.push(c); } }
const trkText = [];
for (const r of trk) { const iv = nz(r[cInv]); if (!iv) { continue; } let b = ''; for (const c of cDeals) { b += ' ' + s(r[c]); } trkText.push({ inv: iv, blob: nz(b) }); }

function parseDate(v) {
  const t = s(v); if (!t) { return null; }
  let m = t.match(/^(\d{4})-(\d{2})-(\d{2})/); if (m) { return new Date(Date.UTC(+m[1], +m[2] - 1, +m[3])); }
  m = t.match(/^(\d{1,2})[\/-](\d{1,2})[\/-](\d{4})/); if (m) { return new Date(Date.UTC(+m[3], +m[2] - 1, +m[1])); }
  const d = new Date(t); return isNaN(d.getTime()) ? null : d;
}
function iso(d) { return d.toISOString().slice(0, 10); }
// weekdays strictly between a and b
function weekdaysBetween(a, b) {
  let n = 0; const d = new Date(a.getTime()); d.setUTCDate(d.getUTCDate() + 1);
  while (d < b) { const w = d.getUTCDay(); if (w !== 0 && w !== 6) { n++; } d.setUTCDate(d.getUTCDate() + 1); }
  return n;
}
const TODAY = new Date(Date.UTC(2026, 8, 10));

const pairCount = {}; const byStartup = {}; let sent30All = 0;
for (const p of pipe) {
  const k = nz(p.startup); if (!k) { continue; }
  const key = k + '|' + nz(p.investor); pairCount[key] = (pairCount[key] || 0) + 1;
  if (!byStartup[k]) { byStartup[k] = []; } byStartup[k].push(p);
}
let dupPairs = 0; for (const key of Object.keys(pairCount)) { if (pairCount[key] > 1) { dupPairs++; } }

const rows = [];
for (const r of stRaw) {
  const name = s(r.startup); if (!name || s(r.active).toLowerCase() !== 'yes') { continue; }
  const k = nz(name); const mine = byStartup[k] || [];
  let sent = 0, replied = 0, passed = 0, paused = 0, queued = 0, overdue = 0, sent30 = 0;
  const future = {}; const paired = {};
  for (const p of mine) {
    paired[nz(p.investor)] = 1;
    if (s(p.deal_shared).toLowerCase() === 'yes') {
      sent++; const rr = s(p.investor_response).toLowerCase();
      if (rr) { replied++; } if (rr === 'pass' || rr === 'passed') { passed++; }
      const d = parseDate(p.date_shared); if (d && d <= TODAY && (TODAY - d) / 86400000 <= 30) { sent30++; }
      continue;
    }
    if (s(p.pause).toLowerCase() === 'yes') { paused++; continue; }
    queued++;
    const nd = parseDate(p.next_due);
    if (!nd || nd <= TODAY) { overdue++; } else { future[iso(nd)] = 1; }
  }
  sent30All += sent30;
  for (const t of trkText) { if (k.length > 3 && t.blob.indexOf(k) >= 0) { paired[t.inv] = 1; } }

  // strict headroom still left after the re-match (should be ~0)
  const sTags = tagsOf(r.sector); const si = startupStage(r.stage); const raise = toCr(r.raise_inr_cr);
  let untapped = 0, strictLeft = 0;
  for (const b of book) {
    if (paired[b.key]) { continue; } untapped++;
    let ov = false; for (const t of b.tags) { if (sTags.indexOf(t) >= 0) { ov = true; break; } }
    if (!(b.agnostic || ov)) { continue; }
    if (b.band !== null && !(si >= b.band[0] && si <= b.band[1])) { continue; }
    if (b.floor !== null && !(raise !== null && raise >= b.floor)) { continue; }
    strictLeft++;
  }

  // scheduling gaps: idle weekdays from today to the first dated send, and between dated sends
  const dates = Object.keys(future).sort().map(function (x) { return parseDate(x); });
  let gapMax = 0, gapFrom = '', gapTo = '';
  let prev = TODAY;
  // overdue rows go out on the next morning's run, so they cover the first few weekdays
  const overdueCover = Math.ceil(overdue / 2);
  for (let i = 0; i < dates.length; i++) {
    let g = weekdaysBetween(prev, dates[i]);
    if (i === 0) { g = Math.max(0, g - overdueCover); }
    if (g > gapMax) { gapMax = g; gapFrom = iso(prev); gapTo = iso(dates[i]); }
    prev = dates[i];
  }
  const pace = sent30 / 22;
  rows.push({ startup: name, owner: s(r.owner), queued: queued, overdue: overdue,
    sent: sent, replied: replied, passed: passed, paused: paused, sent_last_30d: sent30,
    pace_per_weekday: Math.round(pace * 100) / 100,
    runway_weekdays: pace > 0 ? Math.round(queued / pace) : null,
    first_due: dates.length ? iso(dates[0]) : '', last_due: dates.length ? iso(dates[dates.length - 1]) : '',
    longest_gap_weekdays: gapMax, gap_from: gapFrom, gap_to: gapTo,
    untapped: untapped, strict_left: strictLeft });
}
return [{ json: { generated: '2026-09-10', pipeline_rows: pipe.length, duplicate_pairs: dupPairs,
  live_investors: book.length, active_startups: rows.length, tracker_rows: trk.length,
  sent_last_30d_all: sent30All, rows: rows } }];
